package com.autoops.workflow.service;import com.autoops.common.security.CurrentUser;import com.autoops.workflow.dto.WorkflowDraftDtos;import com.autoops.workflow.entity.*;import com.autoops.workflow.repository.*;import com.autoops.workflow.validation.WorkflowGraphValidator;import org.springframework.stereotype.Service;import org.springframework.transaction.annotation.Transactional;import java.util.*;@Service public class WorkflowDraftService{private final WorkflowRepository workflows;private final WorkflowStepRepository steps;private final CurrentUser current;private final WorkflowGraphValidator validator;public WorkflowDraftService(WorkflowRepository w,WorkflowStepRepository s,CurrentUser c,WorkflowGraphValidator v){workflows=w;steps=s;current=c;validator=v;}@Transactional public Workflow save(WorkflowDraftDtos.Save d){if(d.nodes()==null||d.nodes().isEmpty())throw new IllegalArgumentException("Workflow requires nodes");var w=new Workflow();w.setName(d.name());w.setDescription(d.description());w.setCreatedBy(current.id());w=workflows.save(w);Map<String,WorkflowStep> map=new LinkedHashMap<>();int pos=0;for(var n:d.nodes()){WorkflowStep s=create(n);s.setWorkflowId(w.getId());s.setName(n.name());s.setDescription(n.description());s.setPosition(n.position()==null?pos++:n.position());s.setRequiresApproval(Boolean.TRUE.equals(n.requiresApproval()));map.put(n.clientId(),steps.save(s));}for(var n:d.nodes()){var s=map.get(n.clientId());if(n.successNextClientId()!=null)s.setSuccessNextStepId(require(map,n.successNextClientId()).getId());if(n.failureNextClientId()!=null)s.setFailureNextStepId(require(map,n.failureNextClientId()).getId());steps.save(s);}validator.validate(new ArrayList<>(map.values()));w.setStatus("ACTIVE");return workflows.save(w);}private WorkflowStep require(Map<String,WorkflowStep>m,String id){var s=m.get(id);if(s==null)throw new IllegalArgumentException("Workflow edge references unknown node");return s;}private WorkflowStep create(WorkflowDraftDtos.Node n){switch(n.type()){case"COMMAND":var c=new CommandStep();c.setCommandDefinitionId(n.commandDefinitionId());c.setCommandTemplate(n.commandTemplate());c.setParameters(n.parameters());c.setRunWithSudo(Boolean.TRUE.equals(n.runWithSudo()));c.setTimeoutSeconds(n.timeoutSeconds()==null?60:n.timeoutSeconds());return c;case"FILE":var f=new FileTransferStep();f.setStoredFileId(n.storedFileId());f.setDestinationPath(n.destinationPath());f.setOverwrite(Boolean.TRUE.equals(n.overwrite()));f.setTimeoutSeconds(n.timeoutSeconds()==null?120:n.timeoutSeconds());return f;case"WAIT":var x=new WaitUntilStep();x.setCheckType(n.checkType());x.setCheckCommand(n.checkCommand());x.setExpectedOutput(n.expectedOutput());x.setCheckIntervalSeconds(n.intervalSeconds()==null?5:n.intervalSeconds());x.setTimeoutSeconds(n.timeoutSeconds()==null?120:n.timeoutSeconds());return x;default:throw new IllegalArgumentException("Unsupported workflow node type");}}}
